BEGIN;
CREATE TABLE IF NOT EXISTS software_factory.cicd_delivery_run_snapshots(tenant_id text NOT NULL,run_id uuid NOT NULL,git_operation_id uuid NOT NULL,purpose text NOT NULL,record_sha256_digest text NOT NULL CHECK(record_sha256_digest ~ '^[0-9a-f]{64}$'),record_json jsonb NOT NULL,evidence_reference text NOT NULL UNIQUE,recorded_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,run_id),FOREIGN KEY(tenant_id,git_operation_id) REFERENCES software_factory.git_evidence(tenant_id,operation_id));
CREATE TABLE IF NOT EXISTS software_factory.cicd_workflow_definitions(tenant_id text NOT NULL,workflow_definition_id text NOT NULL,version text NOT NULL,workflow_sha256_digest text NOT NULL CHECK(workflow_sha256_digest ~ '^[0-9a-f]{64}$'),record_sha256_digest text NOT NULL CHECK(record_sha256_digest ~ '^[0-9a-f]{64}$'),record_json jsonb NOT NULL,evidence_reference text NOT NULL UNIQUE,recorded_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workflow_definition_id,version));
COMMIT;
